package com.smartmanager.nativeapp;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.View;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Read-only network modules; write operations remain disabled until separately tested. */
public final class NetworkActivity extends Activity {private String section;private TextView status;private final ExecutorService worker=Executors.newSingleThreadExecutor();@Override public void onCreate(Bundle b){super.onCreate(b);section=getIntent().getStringExtra("section");LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(16,20,16,30);p.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);p.setBackgroundColor(Color.rgb(237,244,250));ScrollView s=new ScrollView(this);s.addView(p);setContentView(s);TextView t=new TextView(this);t.setText(title());t.setTextSize(23);t.setTextColor(Color.rgb(22,47,80));p.addView(t);status=new TextView(this);status.setTextColor(Color.rgb(22,47,80));status.setPadding(8,16,8,16);p.addView(status);load();}private void load(){status.setText("جاري قراءة البيانات الفعلية...");worker.execute(()->{try{android.content.SharedPreferences p=getSharedPreferences("router_connection",MODE_PRIVATE);String pw=new SecureConnectionStore(this).get();try(RouterService r=new RouterService(p.getString("host",""),Integer.parseInt(p.getString("port","8728")),p.getBoolean("tls",false))){r.login(p.getString("user",""),pw==null?"":pw);List<Map<String,String>> rows=r.execute(command(),"=.proplist=.id,name,interface,status,disabled,rx-byte,tx-byte,rate-limit,address,network");StringBuilder b=new StringBuilder();for(Map<String,String> row:rows){for(Map.Entry<String,String> e:row.entrySet())b.append(e.getKey()).append(": ").append(e.getValue()).append("  ");b.append('\n');}ui(()->status.setText(rows.isEmpty()?"لا توجد بيانات مدعومة أو لا توجد صلاحية":b.toString()));}}catch(Exception e){ui(()->status.setText("غير متاح: "+(e.getMessage()==null?"خطأ":e.getMessage())));}});}private String command(){if("interfaces".equals(section))return "/interface/print";if("ip".equals(section))return "/ip/address/print";if("dhcp".equals(section))return "/ip/dhcp-server/lease/print";if("dns".equals(section))return "/ip/dns/print";if("queues".equals(section))return "/queue/simple/print";return "/ip/firewall/filter/print";}private String title(){return "interfaces".equals(section)?"الواجهات":"ip".equals(section)?"عناوين IP":"dhcp".equals(section)?"DHCP":"dns".equals(section)?"DNS":"queues".equals(section)?"الطوابير":"Firewall";}private void ui(Runnable r){runOnUiThread(r);}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}}
